import java.util.*;

class Solution {
    public int countEqualPairs(int[] nums) {
        Map<Integer, Integer> count = new HashMap<>();
        int pairs = 0;
        for (int x : nums) {
            pairs += count.getOrDefault(x, 0);
            count.put(x, count.getOrDefault(x, 0) + 1);
        }
        return pairs;
    }
}

