class Solution {
    public int[] prefixProducts(int[] nums) {
        int[] out = new int[nums.length];
        int running = 1;
        for (int i = 0; i < nums.length; i++) {
            out[i] = running;      // product of nums[0..i-1]
            running *= nums[i];    // now include nums[i] for the next slot
        }
        return out;
    }
}
